def gen(rng):
    def fmt(qs):
        return str(len(qs)) + '\n' + '\n'.join('%d %d' % p for p in qs)

    M = 2 ** 32 - 1
    tests = [fmt([(0xabcd, 17)]), fmt([(0, 1)]), fmt([(0, 32)]), fmt([(M, 1)]), fmt([(M, 32)]),
             fmt([(0xabcd, 1), (0xabcd, 2), (0xabcd, 16), (0xabcd, 17), (0xabcd, 18)]),
             fmt([(0x1abcd, 17)]), fmt([(0x80000000, 32), (0x80000000, 31)])]
    for _ in range(30):
        tests.append(fmt([(rng.randint(0, M), rng.randint(1, 32)) for _ in range(rng.randint(1, 12))]))
    for _ in range(5):
        tests.append(fmt([(rng.randint(0, 2 ** rng.randint(1, 32) - 1), rng.randint(1, 32)) for _ in range(rng.randint(1, 12))]))
    tests.append(fmt([(rng.randint(0, M), rng.randint(1, 32)) for _ in range(100000)]))
    tests.append(fmt([(M - rng.randint(0, 3), 32) for _ in range(100000)]))
    tests.append(fmt([(rng.randint(0, 2 ** 20), 17) for _ in range(100000)]))
    return tests

